interface User {
  id: number;
  name: string;
}

const USERS: User[] = [
  { id: 1, name: 'ada' },
  { id: 2, name: 'grace' },
];

export function userName(id: number): string {
  const user = USERS.find((u) => u.id === id);
  return user.name;
}

